179	/// What a test runs inside a request ([`Lazy::between`]).
180	#[cfg(test)]
181	type Between = Box<dyn FnOnce(&Revision) + Send>;
182	
183	impl Lazy {
184	    /// When this revision follows again a walk that passed a file it could not read: once it is due.
185	    fn retry(&self) -> dependency_types::Retry {
186	        dependency_types::Retry::Due { now: self.clock.now(), edits: self.edits, load: 0 }
187	    }
188	}
189	
190	/// A session's time for [`dependency_types::Retry`]; a test sets it.
191	#[derive(Default)]
192	pub(super) struct RetryClock {
193	    #[cfg(test)]
194	    set: Mutex<Option<Instant>>,
195	}
196	
197	impl RetryClock {
198	    fn now(&self) -> Instant {
199	        #[cfg(test)]
200	        if let Some(now) = *self.set.lock().unwrap_or_else(|poisoned| poisoned.into_inner()) {
201	            return now;
202	        }
203	        Instant::now()
204	    }
205	}
