330	    /// The revision after `changed` was edited, created or deleted, and the keys whose answers may differ. The memo
331	    /// keeps every entry whose resolution did not read `changed`; the dependency layer carries over as it stands.
332	    pub(super) fn next_lazy(
333	        &self,
334	        options: &PipelineOptions,
335	        changed: &Utf8Path,
336	    ) -> Option<(Revision, IncrementalUpdate)> {
337	        let previous = self.lazy.as_ref()?;
338	        if !is_source_file(changed, &options.src_dirs, &options.exclude_patterns, self.source_files()) {
339	            return None;
340	        }
341	        let start = Instant::now();
342	        let Applied { global, named_types, file_diagnostics, files, change, demands, .. } =
343	            self.apply_change(options, changed, false);
344	        let global = Arc::new(global);
345	        let named_types = Arc::new(named_types);
346	
347	        let mut file_demands = previous.demands.clone();
348	        match demands.is_empty() {
349	            true => file_demands.remove(change.file.as_str()),
350	            false => file_demands.insert(PathKey::from(change.file), Arc::from(demands)),
351	        };
352	        let by_name = group_by_name(&global, options);
353	        let memo: DashMap<ComponentId, Arc<Resolved>, FxBuildHasher> = DashMap::default();
354	        let mut touched: FxHashSet<String> = FxHashSet::default();
355	        let mut affected_files: Vec<Utf8PathBuf> = Vec::new();
356	        for entry in previous.memo.iter() {
357	            let (id, resolved) = (entry.key(), entry.value());
358	            let kept = id.file != change.file
359	                && !resolved.affected_by(&change)
360	                && by_name.get(&id.name).is_some_and(|group| group.iter().any(|(candidate, _)| candidate == id));
361	            if kept {
362	                memo.insert(id.clone(), resolved.clone());
363	            } else {
364	                touched.insert(id.name.clone());
365	                affected_files.push(id.file.clone());
366	            }
367	        }
368	        // A provisional answer is never carried over: the edit makes every walk past an unreadable file due, so each
369	        // may answer differently, whatever file it read.
370	        for entry in previous.provisional.iter() {
371	            touched.insert(entry.key().name.clone());
372	            affected_files.push(entry.key().file.clone());
373	        }
374	        // A name the changed file declared before or after keeps no memo, but its keys can still move.
375	        for groups in [&previous.by_name, &by_name] {
376	            for (name, group) in groups {
377	                if group.iter().any(|(id, _)| id.file == change.file) {
378	                    touched.insert(name.clone());
379	                }
380	            }
381	        }
382	        affected_files.sort();
383	        affected_files.dedup();
384	
385	        let layer = previous.engine.load().layer.clone();
386	        let engine = Engine::new(&global, options, &self.ambient_global_files, &named_types, layer, &self.react_types);
387	        // A kept answer is decided again against the new call sites, so an edit to a consumer can change its `used`
388	        // lists without touching its resolution. The new sites are the ones the next answer reads.
389	        if memo.iter().any(|entry| entry.value().evidence.is_some()) {
390	            let before = relevance_inputs::project_sites(&previous.engine.load().ctx);
391	            let after = relevance_inputs::project_sites(&engine.ctx);
392	            for entry in memo.iter().filter(|entry| entry.value().redecided(&before, &after)) {
393	                touched.insert(entry.key().name.clone());
394	            }
395	        }
396	        let next = Revision {
397	            id: self.id + 1,
398	            global,
399	            named_types,
400	            dependencies: None,
401	            react_types: self.react_types.clone(),
402	            ambient_global_files: self.ambient_global_files.clone(),
403	            head_diagnostics: self.head_diagnostics.clone(),
404	            file_diagnostics,
405	            lib_diagnostics: self.lib_diagnostics.clone(),
406	            tail_diagnostics: self.tail_diagnostics.clone(),
407	            resolved: FxHashMap::default(),
408	            sites: Arc::default(),
409	            files: Arc::new(files),
410	            dts_files_parsed: self.dts_files_parsed,
411	            dts_cache_hits: self.dts_cache_hits,
412	            duration_ms: self.duration_ms,
413	            output: Arc::new(empty_output()),
414	            keys: FxHashMap::default(),
415	            lazy: Some(Lazy {
416	                demands: file_demands,
417	                by_name,
418	                memo,
419	                engine: ArcSwap::from_pointee(engine),
420	                growing: Mutex::new(()),
421	                whole_demand_started: std::sync::atomic::AtomicBool::new(false),
422	                whole_demand_thread: Mutex::new(None),
423	                growths: std::sync::atomic::AtomicUsize::new(0),
424	                // An edit makes every walk past an unreadable file due: no provisional answer carries over.
425	                provisional: DashMap::default(),
426	                clock: previous.clock.clone(),
427	                edits: previous.edits + 1,
428	                load_ids: previous.load_ids.clone(),
429	                #[cfg(test)]
430	                resolutions: std::sync::atomic::AtomicUsize::new(0),
431	                #[cfg(test)]
432	                loads: std::sync::atomic::AtomicUsize::new(0),
433	                #[cfg(test)]
434	                between: Mutex::new(None),
435	            }),
436	        };
437	        let update = self.lazy_delta(&next, options, &touched, affected_files, start);
438	        Some((next, update))
439	    }
