441	    /// The revision after a change that can alter how every import resolves, rebuilt from scratch. Every name the
442	    /// previous revision had resolved is reported, since any answer may differ.
443	    pub(super) fn rebuilt_lazy(&self, options: &PipelineOptions) -> Option<(Revision, IncrementalUpdate)> {
444	        let previous = self.lazy.as_ref()?;
445	        let start = Instant::now();
446	        let next = Revision::cold_lazy(options, self.id + 1);
447	        let touched: FxHashSet<String> = previous.memo.iter().map(|entry| entry.key().name.clone()).collect();
448	        let mut affected_files: Vec<Utf8PathBuf> = previous.memo.iter().map(|entry| entry.key().file.clone()).collect();
449	        affected_files.sort();
450	        affected_files.dedup();
451	        let update = self.lazy_delta(&next, options, &touched, affected_files, start);
452	        Some((next, update))
453	    }
454	
455	    /// The delta from this lazy revision to `next`: the keys of every `touched` name there, and the keys it had that
456	    /// `next` does not. Answers are not part of it; a consumer asks again.
457	    fn lazy_delta(
458	        &self,
459	        next: &Revision,
460	        options: &PipelineOptions,
461	        touched: &FxHashSet<String>,
462	        affected_files: Vec<Utf8PathBuf>,
463	        start: Instant,
464	    ) -> IncrementalUpdate {
465	        let mut updated_keys: Vec<String> = Vec::new();
466	        let mut removed_keys: Vec<String> = Vec::new();
467	        for name in touched {
468	            let now = next.group_keys(options, name, true);
469	            removed_keys.extend(self.group_keys(options, name, true).into_iter().filter(|key| !now.contains(key)));
470	            updated_keys.extend(now);
471	        }
472	        updated_keys.sort();
473	        updated_keys.dedup();
474	        removed_keys.sort();
475	        removed_keys.dedup();
476	        IncrementalUpdate {
477	            revision: next.id,
478	            updated_components: Vec::new(),
479	            updated_keys,
480	            removed_keys,
481	            affected_files,
482	            diagnostics: Vec::new(),
483	            removed_diagnostics: Vec::new(),
484	            duration_ms: start.elapsed().as_millis() as u64,
485	        }
486	    }
