488	    /// `component` resolved, memoized. `None` when the position is not one of this revision's mappings.
489	    fn lazy_resolved(&self, options: &PipelineOptions, id: &ComponentId, index: usize) -> Option<Arc<Resolved>> {
490	        self.lazy_resolved_at(options, id, index).map(|(resolved, _)| resolved)
491	    }
492	
493	    /// [`Self::lazy_resolved`], with the layer a provisional answer was read against: its read warnings are the ones
494	    /// that answer carries, whatever a later load recovered since. `None` for a memoized answer, which no unread walk
495	    /// reached.
496	    fn lazy_resolved_at(
497	        &self,
498	        options: &PipelineOptions,
499	        id: &ComponentId,
500	        index: usize,
501	    ) -> Option<(Arc<Resolved>, Option<Arc<dependency_types::DependencyLayer>>)> {
502	        let lazy = self.lazy.as_ref()?;
503	        if let Some(hit) = lazy.memo.get(id) {
504	            return Some((hit.clone(), None));
505	        }
506	        if let Some(hit) = self.provisional_hit(lazy, id) {
507	            return Some(hit);
508	        }
509	        let mapping = self.global.component_mappings.get(index)?;
510	        // The component's own file almost always reaches its own names; loading them first saves a resolution.
511	        if let Some(seed) = lazy.demands.get(mapping.file_path.as_str()) {
512	            self.grow(options, lazy, seed);
513	        }
514	        let mut asked_for: Vec<dependency_types::Demand> = Vec::new();
515	        loop {
516	            let engine = lazy.engine.load_full();
517	            #[cfg(test)]
518	            lazy.resolutions.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
519	            let (entry, diagnostics, depends_on, evidence, attributes) =
520	                resolve_guarded(&[mapping], &engine.ctx).into_iter().next()?;
521	            // The names the resolution reached that the layer lacks, and the demands below them whose walk passed a
522	            // file that could not be read (the layer's ledger): the next load follows both, the second once due.
523	            let (missing, unread) = match &engine.layer {
524	                Some(layer) => {
525	                    let roots: Vec<Demand> = depends_on
526	                        .files
527	                        .iter()
528	                        .filter_map(|file| lazy.demands.get(file))
529	                        .flat_map(|demands| demands.iter().cloned())
530	                        .collect();
531	                    let retry = lazy.retry();
532	                    let unread = layer.unread(&roots);
533	                    let mut missing = layer.missing_at(&roots, retry);
534	                    missing.extend(layer.missing_at(&unread, retry));
535	                    missing.sort();
536	                    missing.dedup();
537	                    (missing, unread)
538	                }
539	                None => (Vec::new(), Vec::new()),
540	            };
541	            // A resolution against a layer that lacked a name it reached is discarded, and so is its context's memo.
542	            // A load that left the same names missing answered none of them (a demand whose load panicked stays
543	            // unanswered, a file that stays unreadable), so asking again would never end.
544	            if missing.is_empty() || missing == asked_for {
545	                let resolved = Arc::new(Resolved { entry, diagnostics, depends_on, evidence, attributes });
546	                // A walk past a file that could not be read answers more once it is followed again: until then the
547	                // answer holds only provisionally, and never in the memo an edit carries over.
548	                if !unread.is_empty() {
549	                    if let Some(footprint) = engine.layer.as_ref().and_then(|layer| layer.footprint(&unread)) {
550	                        lazy.provisional.insert(id.clone(), (resolved.clone(), footprint));
551	                    }
552	                    return Some((resolved, engine.layer.clone()));
553	                }
554	                return Some((lazy.memo.entry(id.clone()).or_insert(resolved).clone(), None));
555	            }
556	            self.grow(options, lazy, &missing);
557	            asked_for = missing;
558	        }
559	    }
560	
561	    /// The provisional answer for `id` while none of the unread walks it reached is due ([`Lazy::provisional`]): no
562	    /// retry has passed, no edit arrived, and no later load followed one of them again or read one of their files.
563	    fn provisional_hit(
564	        &self,
565	        lazy: &Lazy,
566	        id: &ComponentId,
567	    ) -> Option<(Arc<Resolved>, Option<Arc<dependency_types::DependencyLayer>>)> {
568	        let (resolved, footprint) = lazy.provisional.get(id).map(|entry| entry.value().clone())?;
569	        let layer = lazy.engine.load().layer.clone();
570	        let holds = layer.as_ref().is_some_and(|layer| layer.footprint_holds(&footprint, lazy.clock.now(), lazy.edits));
571	        if holds {
572	            return Some((resolved, layer));
573	        }
574	        lazy.provisional.remove(id);
575	        None
576	    }
577	
578	    /// Once the layer has grown [`WHOLE_DEMAND_AFTER_GROWTHS`] times, load every name the project's files take from a
579	    /// package on a thread of its own, once.
580	    ///
581	    /// Each growth of the layer rebuilds the resolution context, so a session that grows one request at a time pays
582	    /// that rebuild for every new component (Spectrum: 33 rebuilds, about 140 of the 300 ms a project read end to end
583	    /// took). A session that asks about a few components never gets here, and holds only the names they reach; one
584	    /// that reads across the project does, and the later requests find every name loaded. A request that needs a name
585	    /// before the thread has loaded it waits for the same lock and loads it, as it would have anyway.
586	    pub(crate) fn load_whole_demand_in_background(self: &Arc<Self>, options: &PipelineOptions) {
587	        use std::sync::atomic::Ordering::Relaxed;
588	        let Some(lazy) = &self.lazy else { return };
589	        if !options.load_dependencies
590	            || lazy.growths.load(Relaxed) < WHOLE_DEMAND_AFTER_GROWTHS
591	            || lazy.whole_demand_started.swap(true, Relaxed)
592	        {
593	            return;
594	        }
595	        let (revision, options) = (self.clone(), options.clone());
596	        let spawned = std::thread::Builder::new().name("caliper-whole-demand".into()).spawn(move || {
597	            drop(crate::panic_guard::contain_panic("load_whole_demand", || {
598	                let Some(lazy) = &revision.lazy else { return };
599	                let all: Vec<Demand> = lazy.demands.values().flat_map(|demands| demands.iter().cloned()).collect();
600	                revision.grow(&options, lazy, &all);
601	            }));
602	        });
603	        // A thread that cannot start costs the speed-up, never an answer.
604	        if let Ok(handle) = spawned {
605	            *lazy.whole_demand_thread.lock().unwrap_or_else(|poisoned| poisoned.into_inner()) = Some(handle);
606	        }
607	    }
608	
609	    /// Wait until the background load [`Self::load_whole_demand_in_background`] started has finished. Without one,
610	    /// returns at once.
611	    pub(crate) fn wait_for_dependency_load(&self) {
612	        let Some(lazy) = &self.lazy else { return };
613	        let handle = lazy.whole_demand_thread.lock().unwrap_or_else(|poisoned| poisoned.into_inner()).take();
614	        if let Some(handle) = handle {
615	            drop(handle.join());
616	        }
617	    }
618	
619	    /// Whether the session's current context holds this revision's own project index, not a copy of it: growing the
620	    /// layer must not clone the project's declarations.
621	    #[cfg(test)]
622	    pub(crate) fn context_shares_project_index(&self) -> Option<bool> {
623	        let lazy = self.lazy.as_ref()?;
624	        Some(lazy.engine.load().ctx.named_types.shares_declarations_with(&self.named_types))
625	    }
626	
627	    /// How many times the dependency layer grew since this revision was built.
628	    #[cfg(test)]
629	    pub(crate) fn layer_growths(&self) -> usize {
630	        self.lazy.as_ref().map_or(0, |lazy| lazy.growths.load(std::sync::atomic::Ordering::Relaxed))
631	    }
632	
633	    /// Load `demands` into the dependency layer unless a concurrent request already did.
634	    fn grow(&self, options: &PipelineOptions, lazy: &Lazy, demands: &[Demand]) {
635	        let _growing = lazy.growing.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
636	        let engine = lazy.engine.load_full();
637	        let Some(layer) = &engine.layer else { return };
638	        let retry = lazy.retry();
639	        let missing = layer.missing_at(demands, retry);
640	        if missing.is_empty() {
641	            return;
642	        }
643	        let load = lazy.load_ids.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
644	        let retry = match retry {
645	            dependency_types::Retry::Due { now, edits, .. } => dependency_types::Retry::Due { now, edits, load },
646	            always => always,
647	        };
648	        let extended = Arc::new(off_pool(|| dependency_types::load_at(missing, options, Some(layer), retry)));
649	        #[cfg(test)]
650	        lazy.loads.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
651	        // Names that were already loaded, or that no package declares, add nothing the resolver reads, so the
652	        // context and its memos stay; only the record of what was asked for moves on. Such a load (a retry of a file
653	        // that stays unreadable) is no growth either: it brings the background load of every name no nearer.
654	        if extended.resolves_like(layer) {
655	            lazy.engine.store(Arc::new(Engine { layer: Some(extended), ctx: engine.ctx.clone() }));
656	            return;
657	        }
658	        lazy.growths.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
659	        // The new context shares the project's index, import map, resolvers and bare-name tables with the old one;
660	        // rebuilding them for every growth was most of what a session reading across a project spent.
661	        let named_types = Arc::new(self.named_types.with_fallback(extended.named_types.clone()));
662	        let ctx = Arc::new(engine.ctx.over_layer(named_types, Some(extended.clone())));
663	        let next = Engine { layer: Some(extended), ctx };
664	        // A memo that reached a project file whose names the old layer lacked was computed without them, and stays
665	        // behind; the rest hold for the larger layer, so the next component does not rebuild them. So does one that
666	        // read a file whose walk reached an unread one (the old layer's ledger): a project file whose demands did, or a
667	        // package file whose declarations did, since what lay past the file that could not be read is missing from it.
668	        let unread = layer.unread_walks();
669	        let unread_project: FxHashSet<&str> = match unread.is_empty() {
670	            true => FxHashSet::default(),
671	            false => lazy
672	                .demands
673	                .iter()
674	                .filter(|(_, demands)| unread.reached_by(demands))
675	                .map(|(file, _)| std::borrow::Borrow::<str>::borrow(file))
676	                .collect(),
677	        };
678	        let kept = |file: &str| {
679	            lazy.demands.get(file).is_none_or(|demands| layer.covers(demands))
680	                && !unread_project.contains(file)
681	                && !unread.declared_in(file)
682	        };
683	        next.ctx.inherit_memos(&engine.ctx, |deps, read_in| {
684	            kept(read_in) && deps.files.iter().all(|file| kept(std::borrow::Borrow::<str>::borrow(file)))
685	        });
686	        lazy.engine.store(Arc::new(next));
687	    }
688	
689	    /// The keys a batch run publishes the components named `name` under, with each key's position in the group.
690	    /// Only an imported-member alias can be left out (when its package isn't loaded it has nothing to show), so only
691	    /// those are resolved to decide. With `listing`, a session that loads dependencies assumes they are all published
692	    /// instead: deciding would load the package of every alias in the project.
693	    fn group_positions(&self, options: &PipelineOptions, name: &str, listing: bool) -> Vec<(String, usize)> {
694	        let Some(group) = self.lazy.as_ref().and_then(|lazy| lazy.by_name.get(name)) else { return Vec::new() };
695	        let mut keyed: Vec<(String, usize)> = Vec::with_capacity(group.len());
696	        let mut published = 0;
697	        for (position, (id, index)) in group.iter().enumerate() {
698	            let Some(mapping) = self.global.component_mappings.get(*index) else { continue };
699	            let assumed = listing && options.load_dependencies;
700	            if matches!(mapping.rule, DetectionRule::ImportedMemberAlias | DetectionRule::FactoryResult) && !assumed {
701	                let empty = self
702	                    .lazy_resolved(options, id, *index)
703	                    .is_some_and(|resolved| resolved.entry.props.is_empty() && resolved.entry.inheritance.is_empty());
704	                if empty {
705	                    continue;
706	                }
707	            }
708	            published += 1;
709	            // The first occurrence of a name keeps it bare; later ones take their file path, which is unique per file.
710	            let key = if published == 1 { name.to_owned() } else { format!("{name} ({})", mapping.file_path) };
711	            // Two components with one key: the later one is kept, as in the output map.
712	            match keyed.iter_mut().find(|(existing, _)| *existing == key) {
713	                Some(slot) => slot.1 = position,
714	                None => keyed.push((key, position)),
715	            }
716	        }
717	        keyed
718	    }
