1052	    /// The layer loads and component resolutions `request` cost.
1053	    fn cost(revision: &Revision, request: impl FnOnce()) -> (usize, usize) {
1054	        let lazy = revision.lazy.as_ref().unwrap();
1055	        let before = (lazy.loads.load(Relaxed), lazy.resolutions.load(Relaxed));
1056	        request();
1057	        (lazy.loads.load(Relaxed) - before.0, lazy.resolutions.load(Relaxed) - before.1)
1058	    }
