1098	        let start = Instant::now();
1099	        set_clock(&revision, start);
1100	        let ask = |key: &str| revision.lazy_component(&options, key).unwrap();
1101	
1102	        assert_eq!(cost(&revision, || assert_eq!(props(&ask("U1")), ["good", "own"])), (1, 1));
1103	        assert_eq!(cost(&revision, || assert_eq!(props(&ask("A")), ["own"])), (1, 1), "the first request behind it");
1104	        for request in 0..5 {
1105	            assert_eq!(cost(&revision, || assert_eq!(props(&ask("A")), ["own"])), (0, 0), "request {request}");
1106	        }
1107	        let before = memo_files(&revision);
1108	        assert!(before.contains("U1.tsx") && before.contains("A.tsx"), "{before:?}");
1109	        assert_eq!(cost(&revision, || assert_eq!(props(&ask("U2")), ["other", "own"])), (1, 1));
1110	        let after = memo_files(&revision);
1111	        assert!(after.contains("U1.tsx"), "an unrelated component's memos are kept: {after:?}");
1112	        assert!(!after.contains("A.tsx"), "the memos read behind the unread walk are not: {after:?}");
