64	/// A request in flight. Every caller for the same component and version of its file waits on it instead of asking the
65	/// checker again.
66	struct Pending {
67	    /// What the checker answers it at; a caller someone is waiting for raises it on joining.
68	    priority: SharedPriority,
69	    settled: Mutex<Option<Settled>>,
70	    ready: Condvar,
71	}
72	
73	impl Pending {
74	    fn new(priority: Priority) -> Self {
75	        Self { priority: SharedPriority::new(priority), settled: Mutex::new(None), ready: Condvar::new() }
76	    }
77	
78	    fn settle(&self, settled: Settled) {
79	        *self.settled.lock().unwrap_or_else(PoisonError::into_inner) = Some(settled);
80	        self.ready.notify_all();
81	    }
82	
83	    /// What became of the request, if that is known within `wait`.
84	    fn wait(&self, wait: Duration) -> Option<Settled> {
85	        let settled = self.settled.lock().unwrap_or_else(PoisonError::into_inner);
86	        let (settled, _) = self
87	            .ready
88	            .wait_timeout_while(settled, wait, |settled| settled.is_none())
89	            .unwrap_or_else(PoisonError::into_inner);
90	        settled.clone()
91	    }
92	}
