94	/// What the checker said about one component at one version of its file, what it is still being asked, and the
95	/// generation they belong to.
96	#[derive(Default)]
97	struct AnswerCache {
98	    /// Raised by every [`SemanticHook::invalidate`]; an answer asked for under an earlier one is not stored.
99	    generation: u64,
100	    answers: FxHashMap<(String, u64), Answered>,
101	    /// Requests in flight under the current generation, by the same key as `answers`.
102	    pending: FxHashMap<(String, u64), Arc<Pending>>,
103	    /// The requests the checker last answered with nothing ([`Settled::Degraded`]), when, and what it said. Not an
104	    /// answer: a request within [`DEGRADED_RETRY`] of it gets the structural props and these diagnostics without asking
105	    /// the checker, which would spend a restart or a timeout to fail again; one after it asks again.
106	    degraded: FxHashMap<(String, u64), (Instant, Vec<Diagnostic>)>,
107	    /// The one copy of each prop the kept answers hold, for this generation.
108	    props: PropInterner,
109	}
110	
111	/// The most refusals [`AnswerCache::degraded`] holds. A key asked once and never again would otherwise stay for the
112	/// session; past the bound the expired ones go first, then the oldest.
113	const DEGRADED_HELD: usize = 256;
114	
115	impl AnswerCache {
116	    /// Hold `key`'s refusal from `at`. At the bound, the refusals past [`DEGRADED_RETRY`] are dropped first (a scan
117	    /// only when the map is full), then the oldest, so the map never holds more than [`DEGRADED_HELD`].
118	    fn hold_degraded(&mut self, key: (String, u64), at: Instant, said: Vec<Diagnostic>) {
119	        if self.degraded.len() >= DEGRADED_HELD && !self.degraded.contains_key(&key) {
120	            self.degraded.retain(|_, (held, _)| at.saturating_duration_since(*held) < DEGRADED_RETRY);
121	            if self.degraded.len() >= DEGRADED_HELD {
122	                let oldest = self.degraded.iter().min_by_key(|(_, (held, _))| *held).map(|(key, _)| key.clone());
123	                oldest.map(|oldest| self.degraded.remove(&oldest));
124	            }
125	        }
126	        self.degraded.insert(key, (at, said));
127	    }
