516	    #[test]
517	    fn kept_answers_share_one_copy_of_an_equal_prop_until_the_cache_is_invalidated() {
518	        let mut cache = AnswerCache::default();
519	        let first = cache.shared(component("A", &["color", "size"]));
520	        let second = cache.shared(component("B", &["color", "label"]));
521	
522	        assert!(Arc::ptr_eq(&first.props[0], &second.props[0]), "both answers hold the one `color`");
523	        assert!(!Arc::ptr_eq(&first.props[1], &second.props[1]));
524	        assert_eq!(second.key, "B");
525	        assert_eq!(second.props.iter().map(|prop| prop.name.as_str()).collect::<Vec<_>>(), ["color", "label"]);
526	
527	        // What `invalidate` does to the cache: a later answer no longer reaches the props of the dropped ones.
528	        cache.props = PropInterner::default();
529	        let third = cache.shared(component("C", &["color"]));
530	        assert!(!Arc::ptr_eq(&first.props[0], &third.props[0]));
531	    }
